package router

import (
	"net/http"
	"time"
)

// Router wires the orders API handlers onto a mux.
type Router struct {
	mux     *http.ServeMux
	timeout time.Duration
}

// New builds a Router with the given per-request timeout.
func New(timeout time.Duration) *Router {
	r := &Router{mux: http.NewServeMux(), timeout: timeout}
	r.mux.HandleFunc("/v1/orders", r.listOrders)
	r.mux.HandleFunc("/v1/orders/", r.getOrder)
	r.mux.HandleFunc("/healthz", r.healthz)
	return r
}

func (r *Router) listOrders(w http.ResponseWriter, req *http.Request) {
	if req.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("content-type", "application/json")
	w.WriteHeader(http.StatusOK)
}

func (r *Router) getOrder(w http.ResponseWriter, req *http.Request) {
	id := req.URL.Path[len("/v1/orders/"):]
	if id == "" {
		http.NotFound(w, req)
		return
	}
	w.Header().Set("content-type", "application/json")
}

func (r *Router) healthz(w http.ResponseWriter, req *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}

